        Array.prototype.forEach.call(lb.querySelectorAll("button"), function (b) { b.setAttribute("aria-pressed", String(b.getAttribute("data-level") === lvl)); });
        Array.prototype.forEach.call(ab.querySelectorAll("button"), function (b) { b.setAttribute("aria-pressed", String(!!on[b.getAttribute("data-addon")])); });
        list.textContent = "";
